7	/// Refresh the given syntax node with as little parsing as possible.
8	///
9	/// Takes the new text, the range in the old text that was replaced and the
10	/// length of the replacement and returns the range in the new text that was
11	/// ultimately reparsed.
12	///
13	/// The high-level API for this function is
14	/// [`Source::edit`](crate::Source::edit).
15	pub fn reparse(
16	    root: &mut SyntaxNode,
17	    text: &str,
18	    replaced: Range<usize>,
19	    replacement_len: usize,
20	) -> Range<usize> {
21	    try_reparse(text, replaced, replacement_len, None, root, 0).unwrap_or_else(|| {
22	        let id = root.span().id();
23	        *root = parse(text);
24	        if let Some(id) = id {
25	            root.numberize(id, Span::FULL).unwrap();
26	        }
27	        0..text.len()
28	    })
29	}
