128	/// Reparse a range of markup expressions, expanding the range exponentially on
129	/// each iteration.
130	fn expand_and_reparse_markup(
131	    text: &str,
132	    replaced: Range<usize>,
133	    replacement_len: usize,
134	    node: &mut SyntaxNode,
135	    overlap: Range<usize>,
136	    offset: usize,
137	    top_level: bool,
138	) -> Option<Range<usize>> {
139	    let children = node.children().as_slice();
140	
141	    // Reparse a segment. Retries until it works, taking exponentially more
142	    // children into account.
143	    let mut expansion = 1;
144	    loop {
145	        // Add slack in both directions.
146	        let mut start = overlap.start.saturating_sub(expansion.max(2));
147	        let mut end = (overlap.end + expansion).min(children.len());
148	
149	        // Expand to the left.
150	        while start > 0 && expand(&children[start]) {
151	            start -= 1;
152	        }
153	
154	        // Expand to the right.
155	        while end < children.len() && expand(&children[end]) {
156	            end += 1;
157	        }
158	
159	        // Also take hash.
160	        if start > 0 && children[start - 1].kind() == SyntaxKind::Hash {
161	            start -= 1;
162	        }
163	
164	        // Synthesize what `at_start` and `nesting` would be at the start of the
165	        // reparse.
166	        let mut prefix_len = 0;
167	        let mut nesting = 0;
168	        let mut at_start = true;
169	        for child in &children[..start] {
170	            prefix_len += child.len();
171	            next_at_start(child, &mut at_start);
172	            next_nesting(child, &mut nesting);
173	        }
174	
175	        // Determine what `at_start` will have to be at the end of the reparse.
176	        let mut prev_len = 0;
177	        let mut prev_at_start_after = at_start;
178	        let mut prev_nesting_after = nesting;
179	        for child in &children[start..end] {
180	            prev_len += child.len();
181	            next_at_start(child, &mut prev_at_start_after);
182	            next_nesting(child, &mut prev_nesting_after);
183	        }
184	
185	        // Determine the range in the new text that we want to reparse.
186	        let shifted = offset + prefix_len;
187	        let new_len = prev_len + replacement_len - replaced.len();
188	        let new_range = shifted..shifted + new_len;
189	        let at_end = end == children.len();
190	
191	        // Reparse!
192	        let reparsed = reparse_markup(
193	            text,
194	            new_range.clone(),
195	            &mut at_start,
196	            &mut nesting,
197	            top_level,
198	        );
199	
200	        if let Some(newborns) = reparsed {
201	            // If more children follow, at_start must match its previous value.
202	            // Similarly, if we children follow or we not top-level the nesting
203	            // must match its previous value.
204	            if (at_end || at_start == prev_at_start_after)
205	                && ((at_end && top_level) || nesting == prev_nesting_after)
206	            {
207	                // Reparsing succeeded, but we can still fail if we're out of
208	                // span numbers to assign to nodes (this is rare).
209	                return node
210	                    .replace_children(start..end, newborns)
211	                    .is_ok()
212	                    .then_some(new_range);
213	            }
214	        }
215	
216	        // If it didn't even work with all children, we give up.
217	        if start == 0 && at_end {
218	            break;
219	        }
220	
221	        // Exponential expansion to both sides.
222	        expansion *= 2;
223	    }
224	
225	    None
226	}
